    mask = pd.Series(False, index=df.index)
    if "system_id" in df.columns:
        mask = mask | df["system_id"].astype(str).str.lower().eq("mv_rad")
    if "name" in df.columns:
        mask = mask | df["name"].astype(str).str.lower().eq("mv_rad")

    if mask.any():
        rows = df[mask]
    elif len(df) == 1:
        rows = df
    else:
        rows = pd.DataFrame()

