# Determine the timezone from system_information for system 'mv_rad'
import pandas as pd

df = feed.system_information.copy()

answer = ""

if isinstance(df, pd.DataFrame) and not df.empty:
    target = "mv_rad"
    # Candidate identifier columns to match the system
    id_cols = [c for c in df.columns if c in ["system_id", "name", "short_name", "operator", "brand", "provider", "id", "slug"]]
    mask = pd.Series(False, index=df.index)
    for c in id_cols:
        # Compare case-insensitively and normalize common separators
        col_vals = df[c].astype(str).str.lower().str.replace("-", "_").str.replace(" ", "_")
        mask = mask | col_vals.eq(target)

    # If no explicit match, and only one row exists, assume it's the intended system
    if not mask.any() and df.shape[0] == 1:
        sel = df.iloc[[0]]
    else:
        sel = df[mask]

    if not sel.empty:
        # Prefer 'timezone' (GBFS v2+), fallback to 'time_zone' if present
        tz_col = "timezone" if "timezone" in sel.columns else ("time_zone" if "time_zone" in sel.columns else None)
        if tz_col is not None:
            val = sel.iloc[0][tz_col]
            if pd.notna(val):
                answer = str(val)

result = {"answer": answer}

