n_languages = 0
if isinstance(data, dict):
    # Prefer counting entries that look like language blocks (contain "feeds")
    n_languages = sum(1 for v in data.values() if isinstance(v, dict) and "feeds" in v)
    # Fallback: if none matched but data is non-empty, count all keys
    if n_languages == 0 and len(data) > 0:
        n_languages = len(data)
elif isinstance(data, list):
    # If data is a list of feeds without language scoping, treat as a single language
    n_languages = 1 if len(data) > 0 else 0
else:
    n_languages = 0

result = {"answer": int(n_languages)}
