import math
import re
import numpy as np
import pandas as pd

df = getattr(feed, "system_pricing_plans", None)

def extract_numeric(x):
    if x is None or (isinstance(x, float) and math.isnan(x)):
        return None
    if isinstance(x, (int, float, np.integer, np.floating)):
        return float(x)
    if isinstance(x, str):
        m = re.search(r"[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?", x.replace(",", "."))
        return float(m.group()) if m else None
    if isinstance(x, dict):
        for k in ["price", "amount", "value", "base_price", "unlock_fee"]:
            if k in x:
                v = extract_numeric(x[k])
                if v is not None:
                    return v
        return None
    if isinstance(x, (list, tuple)):
        for item in x:
            v = extract_numeric(item)
            if v is not None:
                return v
        return None
    try:
        return float(x)
    except Exception:
        return None

price = None
add_info = None

if isinstance(df, pd.DataFrame) and not df.empty:
    row = df.iloc[0]
    # Try common price-related columns
    candidate_cols = ["price", "plan_price", "base_price", "unlock_fee", "amount", "value", "price_amount"]
    for col in candidate_cols:
        if col in df.columns:
            price = extract_numeric(row.get(col))
            if price is not None and not math.isnan(price):
                break
    # Prepare additional info
    plan_name = str(row.get("name")) if "name" in df.columns else None
    plan_id = str(row.get("plan_id")) if "plan_id" in df.columns else None
    currency = str(row.get("currency")) if "currency" in df.columns else None
    parts = []
    if plan_name: parts.append(f"name={plan_name}")
    if plan_id: parts.append(f"plan_id={plan_id}")
    if currency: parts.append(f"currency={currency}")
    add_info = ", ".join(parts) if parts else None

result = {"answer": float(price) if price is not None else None}
if add_info:
    result["additional_info"] = add_info
