import pandas as pd
import numpy as np

df = feed.system_hours if hasattr(feed, "system_hours") else None

days_set = set()
day_abbrs = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
day_full_to_abbr = {
    "monday": "mon",
    "tuesday": "tue",
    "wednesday": "wed",
    "thursday": "thu",
    "friday": "fri",
    "saturday": "sat",
    "sunday": "sun",
}

def is_na(x):
    try:
        return pd.isna(x)
    except Exception:
        return False

def add_days_from_value(val):
    if val is None or is_na(val):
        return
    if isinstance(val, (list, tuple, set)):
        for x in val:
            add_days_from_value(x)
    elif isinstance(val, dict):
        # Prefer explicit 'days' key if present
        if "days" in val:
            add_days_from_value(val["days"])
        else:
            for k, v in val.items():
                # Recurse through nested structures
                add_days_from_value(v)
    elif isinstance(val, str):
        s = val.strip().lower()
        if s in day_abbrs:
            days_set.add(s)
        elif s in day_full_to_abbr:
            days_set.add(day_full_to_abbr[s])
    # ignore other types

if isinstance(df, pd.DataFrame) and not df.empty:
    row = df.iloc[0]

    # 1) Direct 'days' field on the row
    if "days" in row.index:
        add_days_from_value(row["days"])

    # 2) Typical GBFS structure: 'rental_hours' array with objects containing 'days'
    if "rental_hours" in row.index:
        add_days_from_value(row["rental_hours"])

    # 3) Flattened columns that may include days (e.g., rental_hours__0__days or rental_hours__0__days__0)
    for col in row.index:
        col_l = str(col).lower()
        val = row[col]
        if "days" in col_l:
            add_days_from_value(val)
        else:
            # Handle boolean flags like 'monday', 'mon', etc.
            if isinstance(val, bool) and val:
                # Try to extract any day reference from the column name
                matched = None
                for abbr in day_abbrs:
                    if abbr in col_l:
                        matched = abbr
                        break
                if not matched:
                    for full, abbr in day_full_to_abbr.items():
                        if full in col_l:
                            matched = abbr
                            break
                if matched:
                    days_set.add(matched)

# Deterministic output
days_list = sorted(days_set)

result = {"answer": days_list}
```

