vt = getattr(feed, "vehicle_types", None)
name_str = ""

if isinstance(vt, pd.DataFrame) and not vt.empty:
    df = vt.copy()

    # Normalize vehicle_type_id to string for comparison
    if "vehicle_type_id" in df.columns:
        mask_id = df["vehicle_type_id"].astype(str) == "3"
        candidates = df[mask_id].copy()
    else:
        candidates = pd.DataFrame()

    # Attempt to narrow to mv_rad if system-identifying columns exist
    if not candidates.empty:
        mv_key = "mv_rad"
        # Potential columns that could contain a system identifier/name
        possible_sys_cols = [c for c in df.columns if any(k in c.lower() for k in ["system_id", "system", "provider", "operator", "brand", "name"])]
        # Avoid reusing the vehicle_type's own 'name' first; prefer explicit system id fields
        preferred_order = [c for c in possible_sys_cols if "system_id" in c.lower()] + [c for c in possible_sys_cols if "system" in c.lower() and "system_id" not in c.lower()] + [c for c in possible_sys_cols if c not in possible_sys_cols[:0]]
        filtered = None
        for col in preferred_order:
            if col in candidates.columns:
                col_vals = candidates[col].astype(str).str.lower()
                exact_match = candidates[col_vals == mv_key]
                if not exact_match.empty:
                    filtered = exact_match
                    break
        if filtered is not None and not filtered.empty:
            candidates = filtered

        # If still multiple, try to use system_information to match system_id/name
        if len(candidates) > 1:
            si = getattr(feed, "system_information", None)
            if isinstance(si, pd.DataFrame) and not si.empty:
                sys_ids = set()
                if "system_id" in si.columns:
                    sys_ids |= set(si["system_id"].dropna().astype(str).str.lower())
                if "name" in si.columns:
                    sys_ids |= set(si["name"].dropna().astype(str).str.lower())
                # If mv_rad is present in system_information, prefer that
                if mv_key in sys_ids:
                    for col in preferred_order:
                        if col in candidates.columns:
                            col_vals = candidates[col].dropna().astype(str).str.lower()
                            exact_match = candidates[col_vals == mv_key]
                            if not exact_match.empty:
                                candidates = exact_match
                                break

        # Select the first candidate
        row = candidates.iloc[0]

        # Prefer 'name' field; fallback to other descriptive fields
        preferred_name_cols = ["name", "form_factor", "type", "vehicle_type", "vehicle_name", "description"]
        for c in preferred_name_cols:
            if c in candidates.columns:
                val = row.get(c)
                if pd.notna(val):
                    name_str = str(val)
                    break

        if not isinstance(name_str, str):
            name_str = ""
        # Some feeds may have numeric-like names; ensure string
        name_str = "" if name_str.lower() == "nan" else name_str

