station_id_target = "139983"

ans = None

# Look up in station_information
info = feed.station_information.copy()
if "station_id" in info.columns and not info.empty:
    mask = info["station_id"].astype(str) == station_id_target
    if mask.any():
        row = info[mask].iloc[0]

        # 1) Try direct 'capacity'
        if "capacity" in row.index:
            cap_val = pd.to_numeric(pd.Series([row["capacity"]]), errors="coerce").iloc[0]
            if pd.notna(cap_val):
                ans = int(cap_val)

        # 2) Try GBFS v3-style 'vehicle_types_capacity' if present
        if ans is None and "vehicle_types_capacity" in row.index:
            vtc = row["vehicle_types_capacity"]
            # If it's a JSON string, try to parse
            if isinstance(vtc, str):
                try:
                    vtc = json.loads(vtc)
                except Exception:
                    pass
            total = None
            if isinstance(vtc, dict):
                counts = []
                for v in vtc.values():
                    try:
                        v_num = float(v)
                        if pd.notna(v_num):
                            counts.append(v_num)
                    except Exception:
                        continue
                if counts:
                    total = int(sum(counts))
            elif isinstance(vtc, list):
                s = 0
                ok = False
                for item in vtc:
                    if isinstance(item, dict):
                        count = item.get("count") if "count" in item else item.get("capacity") if "capacity" in item else None
                        if count is not None:
                            try:
                                s += int(float(count))
                                ok = True
                            except Exception:
                                continue
                if ok:
                    total = s
            if total is not None:
                ans = total

# 3) Fallback: derive from station_status (num_bikes_available + num_docks_available)
if ans is None:
    status = feed.station_status
    if "station_id" in status.columns and not status.empty:
        srow = status[status["station_id"].astype(str) == station_id_target]
        if not srow.empty:
            nba = pd.to_numeric(srow["num_bikes_available"], errors="coerce").fillna(0).iloc[0] if "num_bikes_available" in srow.columns else 0
            nda = pd.to_numeric(srow["num_docks_available"], errors="coerce").fillna(pd.NA).iloc[0] if "num_docks_available" in srow.columns else pd.NA
            if pd.notna(nda):
                try:
                    ans = int(float(nba) + float(nda))
                except Exception:
                    pass

# Ensure integer or None
if ans is not None:
    try:
        ans = int(ans)
    except Exception:
        ans = None

result = {"answer": ans}
