            nda = pd.to_numeric(srow["num_docks_available"], errors="coerce").fillna(pd.NA).iloc[0] if "num_docks_available" in srow.columns else pd.NA
            if pd.notna(nda):
                try:
                    ans = int(float(nba) + float(nda))
                except Exception:
                    pass

# Ensure integer or None
if ans is not None:
