import pandas as pd
import json

station_id_query = "153216"

cap = None
info_source = None

# 1) Try station_information.capacity
info = feed.station_information.copy()
if "station_id" in info.columns and not info.empty:
    row_info = info[info["station_id"].astype(str) == station_id_query]
    if not row_info.empty:
        row = row_info.iloc[0]
        if "capacity" in row.index:
            val = row.get("capacity")
            if pd.notnull(val):
                try:
                    cap = int(float(val))
                    info_source = "capacity"
                except Exception:
                    pass

        # 2) Try per-vehicle capacity dict and sum it
        if cap is None:
            for col in ["vehicle_capacity", "vehicle_type_capacity"]:
                if col in row.index and pd.notnull(row.get(col)):
                    vc = row.get(col)
                    # If stored as JSON string, parse it
                    if isinstance(vc, str):
                        try:
                            vc_parsed = json.loads(vc)
                            vc = vc_parsed
                        except Exception:
                            vc = None
                    if isinstance(vc, dict):
                        try:
                            cap_sum = 0
                            for v in vc.values():
                                if v is not None:
                                    cap_sum += int(float(v))
                            cap = int(cap_sum)
                            info_source = col
                            break
                        except Exception:
                            pass

# 3) Fallback: derive from current status (bikes + docks)
if cap is None:
    ms = feed.merged_stations()
    if "station_id" in ms.columns and not ms.empty:
        row_ms = ms[ms["station_id"].astype(str) == station_id_query]
        if not row_ms.empty:
            r = row_ms.iloc[0]
            bikes = pd.to_numeric(pd.Series([r.get("num_bikes_available")]), errors="coerce").iloc[0]
            docks = pd.to_numeric(pd.Series([r.get("num_docks_available")]), errors="coerce").iloc[0]
            if pd.notnull(bikes) or pd.notnull(docks):
                bikes = 0 if pd.isna(bikes) else float(bikes)
                docks = 0 if pd.isna(docks) else float(docks)
                cap = int(bikes + docks)
                info_source = "derived_from_status"

# Ensure an integer is returned; default to 0 if not found
cap = int(cap) if cap is not None else 0

additional = None
if info_source is not None:
    additional = f"Capacity from {info_source}"
else:
    additional = "Station not found or capacity unavailable; returned 0"

result = {"answer": cap, "additional_info": additional}
