    if available is None and "num_bikes_available_types" in sub.columns:
        val = row.get("num_bikes_available_types")
        types_dict = None
        if isinstance(val, dict):
            types_dict = val
        elif isinstance(val, str):
            try:
                types_dict = json.loads(val)
            except Exception:
                types_dict = None
        if isinstance(types_dict, dict):
            try:
                available = int(sum(float(v) for v in types_dict.values() if v is not None))
            except Exception:
                available = 0

