    df["_sid_str"] = df["station_id"].astype(str)
    sub = df[df["_sid_str"] == sid]
else:
    sub = pd.DataFrame([])

ans = None
if not sub.empty:
    row = sub.iloc[0]
    # Prefer direct num_docks_available if present
    val = row.get("num_docks_available")
    try:
        if val is not None and not pd.isna(val):
            ans = int(float(val))
    except Exception:
        ans = None

    # Fallback: compute from capacity and bikes if direct field missing
    if ans is None:
        def to_float(v):
            try:
                return float(v)
            except (TypeError, ValueError):
                return float("nan")

        cap = to_float(row.get("capacity"))
        bikes_avail = to_float(row.get("num_bikes_available"))
        bikes_disabled = to_float(row.get("num_bikes_disabled"))
        docks_disabled = to_float(row.get("num_docks_disabled"))

        occupied = 0.0
        if not math.isnan(bikes_avail):
            occupied += bikes_avail
        if not math.isnan(bikes_disabled):
            occupied += bikes_disabled

