    if "region_id" in sr.columns:
        rid_match = sr["region_id"].astype(str).str.lower() == "mv_rad"
    else:
        rid_match = pd.Series([False] * len(sr), index=sr.index)
    if "name" in sr.columns:
        name_match = sr["name"].astype(str).str.strip().str.lower() == "mv_rad"
    else:
        name_match = pd.Series([False] * len(sr), index=sr.index)
    if ("region_id" in sr.columns) and (rid_match.any() or name_match.any()):
        region_ids = set(sr.loc[rid_match | name_match, "region_id"].astype(str).tolist())

# Apply region filter if we found any matching region_ids and station_information has region_id
if region_ids and "region_id" in info.columns:
    info = info[info["region_id"].astype(str).isin(region_ids)].copy()

# If filtering removed all stations, fall back to all stations
if info.empty:
    info = feed.station_information.copy()

# Determine capacity
capacity_series = None
if "capacity" in info.columns:
    capacity_series = pd.to_numeric(info["capacity"], errors="coerce")

# Fallback: estimate capacity from current status if capacity missing or all NaN
if (capacity_series is None) or capacity_series.isna().all():
    status = feed.station_status.copy()
    if not status.empty:
        bikes = pd.to_numeric(status.get("num_bikes_available", 0), errors="coerce").fillna(0)
        docks = pd.to_numeric(status.get("num_docks_available", 0), errors="coerce").fillna(0)
        est_cap = (bikes + docks).astype(float)
        tmp = info[["station_id"]].merge(
            status[["station_id"]].assign(_est_cap=est_cap),
            on="station_id",
            how="left",
        )
        capacity_series = tmp["_est_cap"]
    else:
        capacity_series = pd.Series([float("nan")] * len(info), index=info.index)

# Build selection DataFrame
df_sel = pd.DataFrame({
    "station_id": info["station_id"].astype(str),
    "capacity": capacity_series.astype(float)
}).dropna(subset=["capacity"])

# If still empty, no station found
if df_sel.empty:
