    regions = getattr(feed, "system_regions", None)
    if isinstance(regions, pd.DataFrame) and regions.shape[0] > 0 and "region_id" in regions.columns:
        name_col = "name" if "name" in regions.columns else None
        if name_col:
            reg_norm = regions[name_col].map(normalize)
            match_ids = set(regions.loc[reg_norm == target_norm, "region_id"].astype(str))
            if match_ids and "region_id" in df.columns:
                mask = df["region_id"].astype(str).isin(match_ids)

    # If not found, try direct region_id match
    if (mask is None or not mask.any()) and "region_id" in df.columns:
        direct_region_match = df["region_id"].astype(str).map(normalize) == target_norm
        if direct_region_match.any():
            mask = direct_region_match

    # If still not found, try other likely columns
    if mask is None or not mask.any():
        likely_cols = [c for c in df.columns if any(k in c.lower() for k in ["region", "system", "network", "brand", "provider", "operator", "tenant", "area"])]
        for c in likely_cols:
            try:
                col_norm = df[c].map(normalize)
                candidate = col_norm == target_norm
                if candidate.any():
                    mask = candidate
                    break
            except Exception:
                continue

    # If still not found, check if the entire feed is mv_rad via system_information
    if mask is None or not mask.any():
        sys = getattr(feed, "system_information", None)
        sys_match = False
        if isinstance(sys, pd.DataFrame) and sys.shape[0] > 0:
            row = sys.iloc[0].to_dict()
            for key in ["name", "system_id", "operator", "brand"]:
                if key in row and normalize(row[key]) == target_norm:
                    sys_match = True
                    break
        if sys_match:
            mask = pd.Series(True, index=df.index)
        else:
            # Fallback to all stations (typical when the feed is for a single system)
            mask = pd.Series(True, index=df.index)

    # Compute capacity with fallback to status if capacity missing
    cap = pd.to_numeric(df.get("capacity"), errors="coerce")
    nba = pd.to_numeric(df.get("num_bikes_available"), errors="coerce").fillna(0) if "num_bikes_available" in df.columns else 0
    nda = pd.to_numeric(df.get("num_docks_available"), errors="coerce").fillna(0) if "num_docks_available" in df.columns else 0

    est_cap = cap.copy()
    if isinstance(est_cap, pd.Series):
