    if mask is None or not mask.any():
        likely_cols = [c for c in df.columns if any(k in c.lower() for k in ["region", "system", "network", "brand", "provider", "operator", "tenant", "area"])]
        for c in likely_cols:
            try:
                col_norm = df[c].map(normalize)
                candidate = col_norm == target_norm
                if candidate.any():
                    mask = candidate
                    break
            except Exception:
                continue

    # If still not found, check if the entire feed is mv_rad via system_information
    if mask is None or not mask.any():
        sys = getattr(feed, "system_information", None)
        sys_match = False
        if isinstance(sys, pd.DataFrame) and sys.shape[0] > 0:
            row = sys.iloc[0].to_dict()
            for key in ["name", "system_id", "operator", "brand"]:
                if key in row and normalize(row[key]) == target_norm:
                    sys_match = True
                    break
        if sys_match:
            mask = pd.Series(True, index=df.index)
        else:
            # Fallback to all stations (typical when the feed is for a single system)
            mask = pd.Series(True, index=df.index)

    # Compute capacity with fallback to status if capacity missing
