import pandas as pd
import re

# Merge station info and status to get capacity and num_bikes_available together
df = feed.merged_stations().copy()

# Helper to slugify strings for robust matching (e.g., "MV Rad" -> "mv_rad")
def slugify(x):
    if x is None:
        return None
    s = str(x).lower()
    s = re.sub(r'[^a-z0-9]+', '_', s)
    return s.strip('_')

# Determine region filter for "mv_rad" if regions are present
region_ids = set()

# Try to find matching regions by name or id
sr = getattr(feed, "system_regions", None)
if sr is not None and isinstance(sr, pd.DataFrame) and not sr.empty:
    tmp = sr.copy()
    if "name" in tmp.columns:
        tmp["name_slug"] = tmp["name"].map(slugify)
    else:
        tmp["name_slug"] = None
    if "region_id" in tmp.columns:
        tmp["region_id_slug"] = tmp["region_id"].map(slugify)
    else:
        tmp["region_id_slug"] = None

    matches = tmp[
        (tmp["name_slug"] == "mv_rad") | (tmp["region_id_slug"] == "mv_rad")
    ]
    if "region_id" in tmp.columns and not matches.empty:
        region_ids.update(matches["region_id"].dropna().astype(str).tolist())

# If no region_ids found, check station_information region_id directly
if not region_ids and "region_id" in df.columns:
    # Accept direct match or slugified match to "mv_rad"
    direct_match_ids = df[df["region_id"].astype(str) == "mv_rad"]["region_id"].astype(str).unique().tolist()
    if not direct_match_ids:
        # Slugified comparison
        rid_slug = df["region_id"].astype(str).map(slugify)
        direct_match_ids = df[rid_slug == "mv_rad"]["region_id"].astype(str).unique().tolist()
    region_ids.update(direct_match_ids)

# Apply region filter if applicable
