vt = feed.vehicle_types if hasattr(feed, "vehicle_types") else pd.DataFrame()

# Build set of vehicle_type_ids that are electric-assist bicycles
ebike_type_ids = set()
if isinstance(vt, pd.DataFrame) and not vt.empty:
    vt2 = vt.copy()
    for col in ["vehicle_type_id", "propulsion_type", "form_factor"]:
        if col not in vt2.columns:
            vt2[col] = pd.NA
    vt2["propulsion_type"] = vt2["propulsion_type"].astype(str).str.lower()
    if "form_factor" in vt2.columns:
        vt2["form_factor"] = vt2["form_factor"].astype(str).str.lower()
        mask = vt2["propulsion_type"].eq("electric_assist") & vt2["form_factor"].eq("bicycle")
        # If no form_factor info for some rows, fall back to propulsion_type only
        if not mask.any():
            mask = vt2["propulsion_type"].eq("electric_assist")
    else:
        mask = vt2["propulsion_type"].eq("electric_assist")
    ebike_type_ids = set(vt2.loc[mask, "vehicle_type_id"].astype(str).tolist())

def sum_from_breakdown(colname):
    if colname not in s.columns:
        return None
    # Ensure list-of-dicts
    ser = s[colname].apply(lambda v: v if isinstance(v, list) else [])
    exploded = ser.explode()
    if exploded.dropna().empty:
        return 0
    df_e = pd.json_normalize(exploded.dropna())
    if df_e.empty:
        return 0
    # Standardize column names
    if "vehicle_type_id" not in df_e.columns:
        candidates = [c for c in df_e.columns if ("vehicle" in c and "type" in c and "id" in c)]
        if candidates:
            df_e = df_e.rename(columns={candidates[0]: "vehicle_type_id"})
        else:
            return 0
    count_col = None
    for c in ["count", "num_bikes_available", "num_vehicles_available", "quantity", "total"]:
        if c in df_e.columns:
            count_col = c
            break
    if count_col is None:
        return 0
    # Primary: filter using vehicle_types mapping
    if ebike_type_ids:
        mask_types = df_e["vehicle_type_id"].astype(str).isin(ebike_type_ids)
        return int(df_e.loc[mask_types, count_col].fillna(0).astype(float).sum())
    # Fallback: try to use propulsion_type directly in breakdown if present
    if "propulsion_type" in df_e.columns:
        mask = df_e["propulsion_type"].astype(str).str.lower().eq("electric_assist")
        return int(df_e.loc[mask, count_col].fillna(0).astype(float).sum())
    return None

answer = None
for col in ["num_bikes_available_types", "vehicle_types_available"]:
    tmp = sum_from_breakdown(col)
    if tmp is not None:
        answer = tmp
        break

# Final fallback if breakdowns are unavailable or unmappable
if answer is None:
    if "num_ebikes_available" in s.columns:
        answer = int(s["num_ebikes_available"].fillna(0).astype(float).sum())
    else:
        answer = 0

result = {"answer": int(answer)}
