        human_ids = set(
            vt.loc[
                vt["propulsion_type"].astype(str).str.lower() == "human",
                "vehicle_type_id",
            ].astype(str)
        )

# Common synonym keys that often indicate human-powered bikes in breakdowns
human_key_synonyms = {
    "mechanical",
    "classic",
    "standard",
    "human",
    "pedal",
    "bicycle",
    "bike",
    "push_bike",
    "pushbike",
    "bio",
    "acoustic",
}

def parse_possible_json(v):
    if isinstance(v, str):
        t = v.strip()
        if (t.startswith("{") and t.endswith("}")) or (t.startswith("[") and t.endswith("]")):
            try:
                return ast.literal_eval(t)
            except Exception:
                return v
    return v

total_human = None

# Path 1: Use nested num_bikes_available_types column if present
if "num_bikes_available_types" in df.columns and df["num_bikes_available_types"].notna().any():
    s = df["num_bikes_available_types"].apply(parse_possible_json)

    def count_human_from_val(v):
        c = 0.0
        if isinstance(v, dict):
            for k, val in v.items():
                key = str(k)
                try:
                    cnt = float(val) if val is not None else 0.0
                except Exception:
                    cnt = 0.0
                if (human_ids and key in human_ids) or (key.lower() in human_key_synonyms):
                    c += cnt
        elif isinstance(v, list):
            for it in v:
                if not isinstance(it, dict):
