cargo_ids = set()
vt = getattr(feed, "vehicle_types", None)
if vt is not None and isinstance(vt, pd.DataFrame) and vt.shape[0] > 0:
    cols_lower = {c.lower(): c for c in vt.columns}
    # Normalize column access
    vt_id_col = cols_lower.get("vehicle_type_id") or cols_lower.get("vehicle_type") or cols_lower.get("id")
    form_factor_col = cols_lower.get("form_factor")
    name_col = cols_lower.get("name")
    if vt_id_col:
        ids = vt[vt_id_col].astype(str)
        mask = pd.Series(False, index=vt.index)
        if form_factor_col:
            ff = vt[form_factor_col].astype(str).str.lower()
            mask = mask | ff.str.contains("cargo", na=False)
        if name_col:
            nm = vt[name_col].astype(str).str.lower()
            mask = mask | nm.str.contains("cargo", na=False)
        cargo_ids = set(ids[mask].tolist())

# Fallback heuristics in case vehicle_types is absent or yields no cargo_ids
def looks_like_cargo_id(x: str) -> bool:
    return isinstance(x, str) and ("cargo" in x.lower() or "lasten" in x.lower())  # "Lasten" for German systems

# 2) Helper to parse per-row breakdowns into dict {vehicle_type_id: count}
def parse_breakdown(val):
    # Returns dict of {vehicle_type_id: count}
    out = {}
    if val is None or (isinstance(val, float) and math.isnan(val)):
        return out
    # If it's already a dict or list in Python
    parsed = val
    if isinstance(val, str):
        s = val.strip()
        # Try JSON decode
        try:
            parsed = json.loads(s)
        except Exception:
            # Some feeds may store as python-literal-like; attempt a very constrained eval replacement
            # but avoid eval; fallback to empty
            return out
    if isinstance(parsed, dict):
        # Could be {vehicle_type_id: count} or {"a": {"count": 3}, ...}
        for k, v in parsed.items():
            if isinstance(v, (int, float)) and np.isfinite(v):
                out[str(k)] = float(v)
            elif isinstance(v, dict):
                cnt = v.get("count") or v.get("num_bikes_available") or v.get("num_vehicles_available")
                if isinstance(cnt, (int, float)) and np.isfinite(cnt):
                    out[str(k)] = float(cnt)
    elif isinstance(parsed, list):
        # Expected list of dicts like [{"vehicle_type_id": "...", "count": N}, ...]
        for item in parsed:
            if isinstance(item, dict):
                vt_id = item.get("vehicle_type_id") or item.get("type_id") or item.get("vehicle_type") or item.get("id")
                cnt = item.get("count")
                if cnt is None:
                    cnt = item.get("num_bikes_available", item.get("num_vehicles_available"))
                if vt_id is not None and isinstance(cnt, (int, float)) and np.isfinite(cnt):
                    out[str(vt_id)] = out.get(str(vt_id), 0.0) + float(cnt)
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                vt_id, cnt = item
                if vt_id is not None and isinstance(cnt, (int, float)) and np.isfinite(cnt):
                    out[str(vt_id)] = out.get(str(vt_id), 0.0) + float(cnt)
    return out

# 3) Aggregate counts from station_status
total_cargo = 0.0

# Prefer explicit breakdown columns if present
breakdown_cols = [c for c in ["vehicle_types_available", "num_bikes_available_types", "num_vehicles_available_types"] if c in df.columns]

if breakdown_cols:
    for col in breakdown_cols:
        s = df[col]
        for v in s:
            d = parse_breakdown(v)
            if d:
                for vt_id, cnt in d.items():
                    if cargo_ids:
                        if vt_id in cargo_ids:
                            total_cargo += cnt
                    else:
                        if looks_like_cargo_id(vt_id):
                            total_cargo += cnt
else:
    # Attempt flattened columns like 'vehicle_types_available.<id>' or 'num_bikes_available_types.<id>'
    prefixes = ["vehicle_types_available", "num_bikes_available_types", "num_vehicles_available_types"]
    candidate_cols = []
    for c in df.columns:
        for p in prefixes:
            if c.startswith(p + ".") or c.startswith(p + "[") or c.startswith(p + "_"):
                candidate_cols.append(c)
                break
    # Derive mapping from column -> (inferred vehicle_type_id)
    col_map = {}
    for c in candidate_cols:
        # Try to extract suffix id
        vt_id = None
        # patterns: p.[id], p_[id], p[id]
        for p in prefixes:
            if c.startswith(p + "."):
                vt_id = c[len(p) + 1 :]
                break
            if c.startswith(p + "_"):
                vt_id = c[len(p) + 1 :]
                break
            if c.startswith(p + "[") and c.endswith("]"):
                vt_id = c[len(p) + 1 : -1]
                break
        if vt_id:
            col_map[c] = vt_id

    if col_map:
        if cargo_ids:
            cols_to_sum = [c for c, vt_id in col_map.items() if vt_id in cargo_ids]
        else:
            cols_to_sum = [c for c, vt_id in col_map.items() if looks_like_cargo_id(vt_id)]
        if cols_to_sum:
            total_cargo = float(df[cols_to_sum].apply(pd.to_numeric, errors="coerce").fillna(0).sum().sum())

# Ensure integer output
answer_int = int(round(total_cargo)) if np.isfinite(total_cargo) else 0

result = {"answer": answer_int}
