import pandas as pd
import numpy as np

# Helper: normalize strings
def _norm(s):
    if s is None:
        return ""
    if not isinstance(s, str):
        s = str(s)
    return "".join(ch for ch in s.lower() if ch.isalnum())

target_norm = _norm("mv_rad")

# Start from merged stations (information + status)
df = feed.merged_stations().copy()

# Default: include all stations
mask = pd.Series(True, index=df.index)

# Check if the entire feed corresponds to mv_rad via system_information
feed_is_target = False
si = getattr(feed, "system_information", None)
if isinstance(si, pd.DataFrame) and not si.empty:
    for col in [c for c in ["system_id", "name", "short_name"] if c in si.columns]:
        vals = si[col].dropna().astype(str).unique().tolist()
        if any(_norm(v) == target_norm for v in vals):
            feed_is_target = True
            break

# If not the whole feed, try filtering by system_regions name match
if not feed_is_target:
    r = getattr(feed, "system_regions", None)
    if isinstance(r, pd.DataFrame) and not r.empty and "region_id" in r.columns and "region_id" in df.columns:
        name_cols = [c for c in ["name", "region_name", "short_name", "system_id"] if c in r.columns]
        region_ids = set()
        if name_cols:
            for _, row in r.iterrows():
                if any(_norm(row.get(c)) == target_norm for c in name_cols):
                    region_ids.add(row.get("region_id"))
        if region_ids:
            mask &= df["region_id"].isin(region_ids)

# If still not filtered and there are potential system-identifying columns in station_information, try them
if not feed_is_target and mask.all():
    info = getattr(feed, "station_information", None)
    if isinstance(info, pd.DataFrame) and not info.empty:
        sid_cols = [c for c in ["system_id", "brand", "operator", "provider", "company", "vendor"] if c in info.columns]
        if sid_cols:
            # Find station_ids whose metadata matches mv_rad
            matching_sids = set()
            for _, row in info.iterrows():
                if any(_norm(row.get(c)) == target_norm for c in sid_cols):
                    matching_sids.add(row.get("station_id"))
            if matching_sids:
                mask &= df["station_id"].isin(matching_sids)

df_sub = df[mask].copy()

# Bikes available
if "num_bikes_available" in df_sub.columns:
    bikes = pd.to_numeric(df_sub["num_bikes_available"], errors="coerce").fillna(0)
else:
    bikes = pd.Series(0, index=df_sub.index, dtype=float)

# Docks available: prefer explicit, else derive from capacity if available
if "num_docks_available" in df_sub.columns:
    docks = pd.to_numeric(df_sub["num_docks_available"], errors="coerce").fillna(0)
else:
    if "capacity" in df_sub.columns:
        capacity = pd.to_numeric(df_sub["capacity"], errors="coerce").fillna(0)
        docks = (capacity - bikes).clip(lower=0)
    else:
        docks = pd.Series(0, index=df_sub.index, dtype=float)

count = int((bikes > docks).sum())

