# Prepare merged dataframe with station info and status
df = feed.merged_stations().copy()

target = "mv_rad".lower()

# Determine stations belonging to the 'mv_rad' region
sub_df = pd.DataFrame(columns=df.columns)
if "region_id" in df.columns:
    allowed_rids = set()
    reg = getattr(feed, "system_regions", None)
    if isinstance(reg, pd.DataFrame) and not reg.empty:
        # Collect region_ids where any region attribute matches 'mv_rad' (case-insensitive)
        for col in reg.columns:
            try:
                mask = reg[col].astype(str).str.lower() == target
            except Exception:
                continue
            if mask.any() and "region_id" in reg.columns:
                allowed_rids.update(reg.loc[mask, "region_id"].astype(str).tolist())
        # Also match directly on region_id value
        if "region_id" in reg.columns:
            allowed_rids.update(
                reg.loc[reg["region_id"].astype(str).str.lower() == target, "region_id"].astype(str).tolist()
            )
    if allowed_rids:
        sub_df = df[df["region_id"].astype(str).isin(allowed_rids)]
    else:
        sub_df = df[df["region_id"].astype(str).str.lower() == target]

# If no region filtering possible or no matches found, return empty list
if sub_df.empty:
    result = {"answer": []}
else:
    # Compute top 5 by num_bikes_available (ties broken by station_id ascending for determinism)
    sub_df = sub_df.copy()
    sub_df["__nba"] = pd.to_numeric(sub_df.get("num_bikes_available"), errors="coerce").fillna(0)
    sub_df["__sid"] = sub_df.get("station_id").astype(str)

    top_ids = (
        sub_df.sort_values(["__nba", "__sid"], ascending=[False, True], kind="mergesort")
        .head(5)["__sid"]
        .tolist()
    )
    result = {"answer": top_ids}
