import pandas as pd
import numpy as np

df = feed.merged_stations().copy()

# Determine region filter for "mv_rad"
region_filter_applied = False
mask = pd.Series(False, index=df.index)

# If stations have region_id, try direct match
if "region_id" in df.columns:
    direct_mask = df["region_id"].astype(str) == "mv_rad"
    if direct_mask.any():
        mask = direct_mask
        region_filter_applied = True

# If not matched directly, try resolving via system_regions name->region_id
if not region_filter_applied:
    try:
        reg = feed.system_regions
        if isinstance(reg, pd.DataFrame) and not reg.empty:
            candidate_ids = set()
            if "region_id" in reg.columns:
                candidate_ids |= set(reg.loc[reg["region_id"].astype(str) == "mv_rad", "region_id"].astype(str))
            if "name" in reg.columns and "region_id" in reg.columns:
                candidate_ids |= set(reg.loc[reg["name"].astype(str) == "mv_rad", "region_id"].astype(str))
            if candidate_ids and "region_id" in df.columns:
                mask = df["region_id"].astype(str).isin(candidate_ids)
                if mask.any():
                    region_filter_applied = True
    except Exception:
        pass

# If we cannot confidently filter by region, return empty result
if not region_filter_applied:
    result = {"answer": []}
else:
    sub = df[mask].copy()

    # Compute utilization safely: num_bikes_available / capacity, only where capacity > 0
    cap = pd.to_numeric(sub.get("capacity"), errors="coerce")
    nb = pd.to_numeric(sub.get("num_bikes_available"), errors="coerce")

    valid = (cap > 0) & nb.notna()
    sub = sub[valid].copy()
    if sub.empty:
        result = {"answer": []}
    else:
        sub["utilization"] = (pd.to_numeric(sub["num_bikes_available"], errors="coerce") /
                              pd.to_numeric(sub["capacity"], errors="coerce"))
        sub = sub.replace([np.inf, -np.inf], np.nan).dropna(subset=["utilization"])

        if sub.empty:
            result = {"answer": []}
        else:
            # Deterministic tie-break by station_id ascending
            if "station_id" in sub.columns:
                sub["station_id_str"] = sub["station_id"].astype(str)
            else:
                sub["station_id_str"] = sub.index.astype(str)

            top_ids = (
                sub.sort_values(["utilization", "station_id_str"], ascending=[False, True])
                   .head(5)["station_id_str"]
                   .tolist()
            )

            result = {"answer": top_ids}
