import pandas as pd

# Merge station info and status
df = feed.merged_stations().copy()

target_region = "mv_rad"
candidate_region_ids = set()

# Determine candidate region_ids matching "mv_rad" by name or id (case-insensitive)
if "region_id" in df.columns:
    regions = getattr(feed, "system_regions", None)
    if isinstance(regions, pd.DataFrame) and not regions.empty and "region_id" in regions.columns and "name" in regions.columns:
        mask = regions["name"].astype(str).str.lower() == target_region.lower()
        candidate_region_ids.update(regions.loc[mask, "region_id"].astype(str).tolist())
    reg_ids_lower = df["region_id"].dropna().astype(str).str.lower()
    matched_ids = df.loc[reg_ids_lower == target_region.lower(), "region_id"].astype(str).unique().tolist()
    candidate_region_ids.update(matched_ids)

    # Filter to the region if we found any matching region_ids
    if candidate_region_ids:
        df = df[df["region_id"].astype(str).isin(candidate_region_ids)]
    else:
        df = df.iloc[0:0]  # empty if no region match
else:
    df = df.iloc[0:0]  # no region_id info available

# If no stations after filtering, return empty list
if df.empty:
    result = {"answer": []}
else:
    # Compute docks available (prefer num_docks_available; fallback to capacity - num_bikes_available)
    if "num_docks_available" in df.columns:
        docks = pd.to_numeric(df["num_docks_available"], errors="coerce")
    else:
        cap = pd.to_numeric(df["capacity"], errors="coerce") if "capacity" in df.columns else None
        nba = pd.to_numeric(df["num_bikes_available"], errors="coerce") if "num_bikes_available" in df.columns else None
        if cap is not None and nba is not None:
            docks = cap - nba
        else:
            docks = pd.Series([float("nan")] * len(df), index=df.index)

    docks = docks.clip(lower=0)

    out = pd.DataFrame({
        "station_id_str": df["station_id"].astype(str),
        "docks_avail": docks
    }).dropna(subset=["docks_avail"])

    if out.empty:
        result = {"answer": []}
    else:
        out = out.sort_values(by=["docks_avail", "station_id_str"], ascending=[True, True]).head(5)
        result = {"answer": out["station_id_str"].tolist()}
