    # 2) If no match yet, try direct region_id match
    if not mask_region.any() and "region_id" in df.columns:
        mask_region = df["region_id"].astype(str).str.lower().eq("mv_rad")

    # 3) If still no match, try station_id prefix
    if not mask_region.any():
        sid = df["station_id"].astype(str).str.lower()
        starts = sid.str.startswith("mv_rad")
        contains = sid.str.contains("mv_rad")
        if starts.any():
            mask_region = starts
        elif contains.any():
