        region_ids = set(sr.loc[mask, "region_id"].astype(str)) if "region_id" in sr.columns else set()
        if region_ids:
            if "region_id" in info.columns:
                station_filter_ids = set(info.loc[info["region_id"].astype(str).isin(region_ids), "station_id"].astype(str))
