        if isinstance(x, (list, tuple)):
            return list(x)
        if isinstance(x, dict):
            return [x]
        return []
    sub["vehicle_types_available"] = sub["vehicle_types_available"].apply(norm_list)
    exploded = sub.explode("vehicle_types_available")
    if exploded.shape[0] > 0:
        # Extract vehicle_type_id and count from dicts
        def extract_vt(d):
            if isinstance(d, dict):
                return d.get("vehicle_type_id")
            return None
        def extract_count(d):
            if isinstance(d, dict):
                v = d.get("count", d.get("num_bikes_available", d.get("quantity")))
                try:
                    return float(v)
                except Exception:
                    return 0.0
            return 0.0
        exploded["vt"] = exploded["vehicle_types_available"].apply(extract_vt)
        exploded["cnt"] = exploded["vehicle_types_available"].apply(extract_count)
        mask_pos = (exploded["vt"].notna()) & (exploded["cnt"] > 0)
        pos = exploded.loc[mask_pos, ["station_id", "vt"]].dropna()
        if pos.shape[0] > 0:
            distinct_types_by_station = pos.groupby("station_id")["vt"].nunique()
        else:
            distinct_types_by_station = pd.Series(dtype="int64")
    else:
        distinct_types_by_station = pd.Series(dtype="int64")
elif "num_bikes_available_types" in status.columns:
    used_field = "num_bikes_available_types"
    sub = status[["station_id", "num_bikes_available_types"]].copy()
    # Expand dicts into rows of (station_id, vt, count)
    rows = []
    for _, r in sub.iterrows():
        sid = r.get("station_id")
        d = r.get("num_bikes_available_types")
        if isinstance(d, dict):
            for k, v in d.items():
                try:
                    cnt = float(v)
                except Exception:
                    cnt = 0.0
                if cnt > 0:
                    rows.append((sid, str(k)))
        elif isinstance(d, list):
            # Some feeds might use a list of dicts here too
            for item in d:
                if isinstance(item, dict):
                    vt = item.get("vehicle_type_id")
                    v = item.get("count", item.get("num_bikes_available", item.get("quantity")))
                    try:
                        cnt = float(v)
                    except Exception:
                        cnt = 0.0
                    if vt is not None and cnt > 0:
                        rows.append((sid, str(vt)))
    if rows:
        df_rows = pd.DataFrame(rows, columns=["station_id", "vt"])
        distinct_types_by_station = df_rows.groupby("station_id")["vt"].nunique()
    else:
        distinct_types_by_station = pd.Series(dtype="int64")
else:
    # No per-vehicle-type granularity available
    distinct_types_by_station = pd.Series(dtype="int64")

# Select stations with >1 distinct vehicle types available
if distinct_types_by_station is None or len(distinct_types_by_station) == 0:
    station_ids = []
else:
    station_ids = list(distinct_types_by_station[distinct_types_by_station > 1].index.astype(str))

# Ensure sorting ascending
station_ids_sorted = sorted(station_ids)

additional = None
if used_field is None:
    additional = "No per-vehicle-type availability field found in station_status; returning empty list."
elif station_filter_ids is not None:
    additional = f"Filtered to region mv_rad; used field {used_field}."

result = {"answer": station_ids_sorted}
if additional:
    result["additional_info"] = additional
