import pandas as pd
import json

# Helper: safely parse JSON-like strings
def parse_jsonish(x):
    if isinstance(x, (list, dict)) or pd.isna(x):
        return x
    if isinstance(x, str):
        s = x.strip()
        if (s.startswith("{") and s.endswith("}")) or (s.startswith("[") and s.endswith("]")):
            try:
                return json.loads(s)
            except Exception:
                return None
    return None

# Helper: unify a vehicle_types_available / num_bikes_available_types field into a list of dicts
def unify_items(val):
    if val is None or (isinstance(val, float) and pd.isna(val)):
        return []
    if isinstance(val, dict):
        # mapping like {"cargo_bike": 2, "ebike": 3}
        return [{"vehicle_type_id": str(k), "count": v} for k, v in val.items()]
    if isinstance(val, list):
        out = []
        for e in val:
            if isinstance(e, dict):
                # Try to read common fields
                vid = e.get("vehicle_type_id", e.get("vehicle_type", e.get("type_id", e.get("id", e.get("category", None)))))
                cnt = e.get("count", e.get("num_bikes_available", e.get("quantity", e.get("available", e.get("num_vehicles_available", None)))))
                out.append({
                    "vehicle_type_id": None if vid is None else str(vid),
                    "count": cnt,
                    # keep some optional fields for cargo heuristics
                    "form_factor": e.get("form_factor"),
                    "vehicle_type_name": e.get("vehicle_type_name", e.get("name")),
                    "name": e.get("name"),
                    "type": e.get("type"),
                    "category": e.get("category"),
                })
            else:
                # Unrecognized entry
                continue
        return out
    return []

# Identify target region_ids corresponding to "mv_rad"
target_region_ids = set(["mv_rad"])
try:
    sr = feed.system_regions
    if isinstance(sr, pd.DataFrame) and not sr.empty:
        sr = sr.copy()
        if "region_id" in sr.columns:
            # Direct match on region_id
            rid_matches = set(sr.loc[sr["region_id"].astype(str) == "mv_rad", "region_id"].astype(str))
            target_region_ids |= rid_matches
        # Match on name as well
        name_col = None
        for c in ["name", "region_name", "region"]:
            if c in sr.columns:
                name_col = c
                break
        if name_col is not None:
            name_matches = set(sr.loc[sr[name_col].astype(str).str.casefold() == "mv_rad".casefold(), "region_id"].astype(str)) if "region_id" in sr.columns else set()
            target_region_ids |= name_matches
except Exception:
    pass

# Get stations in the mv_rad region
region_station_ids = set()
info = feed.station_information
if isinstance(info, pd.DataFrame) and not info.empty and "region_id" in info.columns and "station_id" in info.columns:
    region_station_ids = set(info.loc[info["region_id"].astype(str).isin(target_region_ids), "station_id"].astype(str))

# If we can't identify any stations in the region, return empty
if not region_station_ids:
    result = {"answer": []}
else:
    # Determine cargo vehicle_type_ids from vehicle_types metadata (if available)
    cargo_type_ids = set()
    vt = getattr(feed, "vehicle_types", None)
    if isinstance(vt, pd.DataFrame) and not vt.empty:
        cols_text = [c for c in vt.columns if c in ["form_factor", "name", "vehicle_type_name", "vehicle_category", "type", "category", "vehicle_subtype"]]
        mask = pd.Series(False, index=vt.index)
        for c in cols_text:
            mask = mask | vt[c].astype(str).str.contains("cargo", case=False, na=False)
        if "vehicle_type_id" in vt.columns:
            cargo_type_ids = set(vt.loc[mask, "vehicle_type_id"].astype(str))

    # Use merged stations to access status + any type-availability fields
    ms = feed.merged_stations()
    ms = ms.copy()
    if "station_id" in ms.columns:
        ms["station_id"] = ms["station_id"].astype(str)
        ms = ms[ms["station_id"].isin(region_station_ids)]
    else:
        ms = ms.iloc[0:0]  # empty

    stations_with_cargo_from_status = set()
    if not ms.empty:
        # Find columns that may hold type-specific availability
