import pandas as pd
import json

# Helper to safely coerce numeric
def _to_num(s):
    try:
        return pd.to_numeric(s)
    except Exception:
        return pd.Series([pd.NA] * len(s), index=s.index)

# 1) Determine station_ids that are in region "mv_rad"
info = feed.station_information.copy()
station_ids_in_region = pd.Index([])

if not info.empty:
    # Normalize to string for comparison
    if "region_id" in info.columns:
        station_ids_in_region = (
            info.loc[info["region_id"].astype(str) == "mv_rad", "station_id"]
            .astype(str)
            .dropna()
            .unique()
        )
    else:
        # Try to use system_regions to map a region name to region_id if possible
        sr = getattr(feed, "system_regions", pd.DataFrame())
        if not sr.empty:
            region_ids = set()
            # Direct region_id match
            if "region_id" in sr.columns:
                region_ids |= set(sr.loc[sr["region_id"].astype(str) == "mv_rad", "region_id"].astype(str).tolist())
            # Name match (fallback)
            for col in [c for c in sr.columns if sr[c].dtype == object]:
                try:
                    region_ids |= set(sr.loc[sr[col].astype(str) == "mv_rad", "region_id"].astype(str).tolist())
                except Exception:
                    continue
            if region_ids and "region_id" in info.columns:
                station_ids_in_region = (
                    info.loc[info["region_id"].astype(str).isin(region_ids), "station_id"]
                    .astype(str)
                    .dropna()
                    .unique()
                )

# If we still don't have region stations, return empty
if len(station_ids_in_region) == 0:
    result = {"answer": []}
else:
    # 2) Join with station_status to get availability fields
    status = feed.station_status.copy()
    if status.empty or "station_id" not in status.columns:
        result = {"answer": []}
    else:
        status["station_id"] = status["station_id"].astype(str)
        df = status[status["station_id"].isin(set(station_ids_in_region))].copy()

        if df.empty:
            result = {"answer": []}
        else:
            # 3) Compute e-bike availability using multiple possible GBFS representations
            has_ebike = pd.Series(False, index=df.index)

            # 3a) num_ebikes_available (GBFS v2.x common)
            if "num_ebikes_available" in df.columns:
                eb = pd.to_numeric(df["num_ebikes_available"], errors="coerce").fillna(0)
                has_ebike = has_ebike | (eb > 0)

            # 3b) num_bikes_available_types (object/dict with key 'ebike')
            if not has_ebike.all() and "num_bikes_available_types" in df.columns:
                def _extract_ebike_from_types(v):
                    if pd.isna(v):
                        return 0
                    obj = v
                    if isinstance(v, str):
                        try:
                            obj = json.loads(v)
                        except Exception:
                            return 0
                    if isinstance(obj, dict):
                        val = obj.get("ebike", 0)
                        try:
                            return float(val)
                        except Exception:
                            return 0
                    return 0
                eb2 = df["num_bikes_available_types"].apply(_extract_ebike_from_types)
                has_ebike = has_ebike | (pd.to_numeric(eb2, errors="coerce").fillna(0) > 0)

            # 3c) vehicle_types_available + vehicle_types metadata (GBFS v3)
            if (not has_ebike.all()) and ("vehicle_types_available" in df.columns):
                vt = getattr(feed, "vehicle_types", pd.DataFrame())
                e_type_ids = set()
                if not vt.empty:
                    # Normalize columns
                    vt_cols = {c.lower(): c for c in vt.columns}
                    propulsion_col = vt_cols.get("propulsion_type")
                    form_factor_col = vt_cols.get("form_factor") or vt_cols.get("vehicle_type")  # attempt both
                    vtid_col = vt_cols.get("vehicle_type_id") or "vehicle_type_id"
                    temp = vt.copy()
                    # Ensure string for comparisons
                    if propulsion_col in temp.columns:
                        temp = temp[temp[propulsion_col].astype(str).str.lower() == "electric_assist"]
                    if (form_factor_col in temp.columns) and (not temp.empty):
                        # If form factor exists, prefer 'bicycle'
                        mask_bike = temp[form_factor_col].astype(str).str.lower().isin(["bicycle", "bike"])
                        if mask_bike.any():
                            temp = temp[mask_bike]
                    if not temp.empty and vtid_col in temp.columns:
                        e_type_ids = set(temp[vtid_col].astype(str).tolist())

                def _count_e_from_vehicle_types_available(v):
                    if pd.isna(v):
                        return 0
                    obj = v
                    if isinstance(v, str):
                        try:
                            obj = json.loads(v)
                        except Exception:
                            return 0
                    total = 0
                    if isinstance(obj, list):
                        for it in obj:
                            if not isinstance(it, dict):
                                continue
                            vt_id = str(it.get("vehicle_type_id", ""))
                            cnt = it.get("count", it.get("quantity", 0))
                            try:
                                cnt = float(cnt)
                            except Exception:
                                cnt = 0
                            if e_type_ids and vt_id in e_type_ids:
                                total += cnt
                    elif isinstance(obj, dict):
                        # Some feeds might use a dict keyed by vehicle_type_id
                        for vt_id, it in obj.items():
                            cnt = it if isinstance(it, (int, float)) else it.get("count", it.get("quantity", 0)) if isinstance(it, dict) else 0
                            try:
                                cnt = float(cnt)
                            except Exception:
                                cnt = 0
                            if e_type_ids and str(vt_id) in e_type_ids:
                                total += cnt
                    return total

                if e_type_ids:
                    eb3 = df["vehicle_types_available"].apply(_count_e_from_vehicle_types_available)
                    has_ebike = has_ebike | (pd.to_numeric(eb3, errors="coerce").fillna(0) > 0)

            # 3d) Fallback: any column explicitly mentioning 'ebike'
            if not has_ebike.any():
                ecols = [c for c in df.columns if "ebike" in c.lower()]
                if ecols:
                    e_sum = pd.DataFrame({c: pd.to_numeric(df[c], errors="coerce").fillna(0) for c in ecols}).sum(axis=1)
                    has_ebike = has_ebike | (e_sum > 0)

            out_ids = df.loc[has_ebike, "station_id"].astype(str).dropna().unique().tolist()
            out_ids_sorted = sorted(out_ids)

            result = {"answer": out_ids_sorted}
