if "region_id" in df.columns:
    df_region = df[df["region_id"].astype(str) == "775"].copy()
else:
    # If region_id is unavailable, no stations can be filtered; result defaults to NaN -> convert to 0.0
    df_region = df.iloc[0:0].copy()

def parse_total_bikes(row):
    # Prefer direct total if available
    if "num_bikes_available" in row and pd.notna(row["num_bikes_available"]):
        try:
            return float(row["num_bikes_available"])
        except Exception:
            pass
    # Fallback: attempt to sum from num_bikes_available_types if present
    v = row.get("num_bikes_available_types", None)
    if v is None or (isinstance(v, float) and np.isnan(v)):
        return 0.0
    # If stored as JSON string, try to parse
    if isinstance(v, str):
        try:
            v = json.loads(v)
        except Exception:
            return 0.0
    total = 0.0
    if isinstance(v, list):
        for item in v:
            if isinstance(item, dict):
                # Common keys: 'count' or 'num_bikes_available'
                if "count" in item and pd.notna(item["count"]):
                    total += float(item["count"])
                elif "num_bikes_available" in item and pd.notna(item["num_bikes_available"]):
                    total += float(item["num_bikes_available"])
    elif isinstance(v, dict):
        # If dict maps vehicle_type_id -> count, sum numeric values
        if all(isinstance(val, (int, float)) or (isinstance(val, str) and str(val).replace('.','',1).isdigit()) for val in v.values()):
            for val in v.values():
                try:
                    total += float(val)
                except Exception:
                    continue
        else:
            # Single-entry dict with keys like {'vehicle_type_id': 'x', 'count': n}
            if "count" in v and pd.notna(v["count"]):
                total += float(v["count"])
            elif "num_bikes_available" in v and pd.notna(v["num_bikes_available"]):
                total += float(v["num_bikes_available"])
    return float(total)

if df_region.shape[0] == 0:
    avg = 0.0
else:
    if "num_bikes_available" in df_region.columns:
        vals = pd.to_numeric(df_region["num_bikes_available"], errors="coerce").fillna(0.0)
    else:
        vals = df_region.apply(parse_total_bikes, axis=1)
    avg = float(vals.mean()) if len(vals) > 0 else 0.0

result = {"answer": avg}
