import pandas as pd
import numpy as np
import json
import ast

df = feed.merged_stations()

# Filter to region_id '775'
if "region_id" in df.columns:
    df_region = df[df["region_id"].astype(str) == "775"].copy()
else:
    info = feed.station_information
    if "region_id" in info.columns:
        ids = set(info[info["region_id"].astype(str) == "775"]["station_id"].astype(str))
        df_region = df[df["station_id"].astype(str).isin(ids)].copy()
    else:
        # If region_id not available anywhere, no stations match the filter
        df_region = df.iloc[0:0].copy()

# If no stations after region filter, return None
if df_region.shape[0] == 0:
    result = {"answer": None}
else:
    # Base numerator: total bikes available
    num = pd.to_numeric(df_region.get("num_bikes_available"), errors="coerce").fillna(0).astype(float)

    # Try to refine numerator for vehicle type 'mv_rad' if per-type availability exists
    mv_num = None
    vt_col = None
    for col in ["vehicle_types_available", "vehicle_types_available_station", "vehicle_types_available_list"]:
        if col in df_region.columns:
            vt_col = col
            break

    def parse_list(val):
        # Ensure we have a Python list of dicts
        if isinstance(val, (list, tuple)):
            return val
        if isinstance(val, str):
            try:
                return json.loads(val)
            except Exception:
                try:
                    return ast.literal_eval(val)
                except Exception:
                    return []
        return []

    def count_for_mv_rad(entry_list):
        total = 0.0
        found = False
        for item in entry_list:
            if not isinstance(item, dict):
                continue
            vt = item.get("vehicle_type_id")
            if vt is None:
                vt = item.get("vehicle_type") or item.get("type_id") or item.get("id")
            if vt is not None and str(vt) == "mv_rad":
                c = item.get("count")
                if c is None:
                    c = item.get("num_bikes_available") or item.get("quantity")
                try:
                    c = float(c)
                except Exception:
                    c = 0.0
                total += c
                found = True
        if found:
            return total
        return np.nan

    if vt_col is not None:
        parsed = df_region[vt_col].apply(parse_list)
        mv_counts = parsed.apply(count_for_mv_rad)
        if mv_counts.notna().any():
            mv_num = mv_counts.fillna(0.0).astype(float)

    if mv_num is not None:
        numerator = mv_num
    else:
        numerator = num

    # Determine capacity (prefer 'capacity', fallback to 'dock_count')
    capacity = None
    if "capacity" in df_region.columns:
        capacity = pd.to_numeric(df_region["capacity"], errors="coerce")
    if (capacity is None) or (capacity.notna().sum() == 0):
        if "dock_count" in df_region.columns:
            capacity = pd.to_numeric(df_region["dock_count"], errors="coerce")
        else:
            capacity = pd.Series(np.nan, index=df_region.index)

    # Also get docks available to compute occupancy if capacity is missing
    docks_avail = pd.to_numeric(df_region.get("num_docks_available"), errors="coerce")

    # Compute per-station utilization ratio
    denom_capacity = capacity.where(capacity > 0)
    ratio_cap = numerator / denom_capacity

    denom_occ = (numerator + docks_avail).where((numerator + docks_avail) > 0)
    ratio_occ = numerator / denom_occ

    ratio = ratio_cap.where(ratio_cap.notna(), ratio_occ)
    # Clip to [0,1] to avoid anomalies
    ratio = ratio.clip(lower=0.0, upper=1.0)

