        # GBFS v2.3+ typically uses form_factor 'bicycle' (and variants); include cargo/pedelec if present
        bike_like_form_factors = set(
            ["bicycle", "cargo_bicycle", "pedelec", "electric_bicycle", "e_bike"]
        )
        ff_col = "form_factor" if "form_factor" in vt.columns else None
        if ff_col is not None:
