            bike_type_ids = set(vt.loc[vt["__is_bike__"] == True, "vehicle_type_id"].astype(str))
        else:
            # If no form_factor metadata, we cannot distinguish; treat all as bikes
            bike_type_ids = set(vt["vehicle_type_id"].astype(str))

        def count_bikes(vta):
            if isinstance(vta, list):
