                return total
            return 0.0

        return dfi["vehicle_types_available"].apply(count_bikes).astype(float)

    # Next fallback: use num_vehicles_available if present (may include non-bikes)
    if "num_vehicles_available" in dfi.columns and dfi["num_vehicles_available"].notna().any():
        return dfi["num_vehicles_available"].astype(float).fillna(0.0)

