import pandas as pd
import numpy as np
import json

# Helper to safely parse JSON-like strings
def _maybe_json_load(x):
    if isinstance(x, (list, dict)) or x is None or (isinstance(x, float) and np.isnan(x)):
        return x
    if isinstance(x, str):
        x = x.strip()
        if (x.startswith("{") and x.endswith("}")) or (x.startswith("[") and x.endswith("]")):
            try:
                return json.loads(x)
            except Exception:
                return None
    return x

# Extract count for a given vehicle_type_id from a heterogeneous object
def _extract_count_for_type(obj, vehicle_type_id):
    obj = _maybe_json_load(obj)
    if obj is None or (isinstance(obj, float) and np.isnan(obj)):
        return np.nan
    # List of dicts like [{"vehicle_type_id":"mv_rad","count":7}, ...]
    if isinstance(obj, list):
        total = 0.0
        found = False
        for it in obj:
            if isinstance(it, dict):
                # Common keys: vehicle_type_id, bike_type, vehicle_type, form_factor, etc.
                for key_name in ("vehicle_type_id", "bike_type", "vehicle_type", "type", "form_factor"):
                    key_val = it.get(key_name)
                    if key_val is not None and str(key_val) == str(vehicle_type_id):
                        cnt = it.get("count")
                        if cnt is None:
                            # Some feeds might use "num_bikes_available" per item
                            cnt = it.get("num_bikes_available")
                        if cnt is not None:
                            try:
                                total += float(cnt)
                                found = True
                            except Exception:
                                pass
        return total if found else np.nan
    # Dict mapping type->count
    if isinstance(obj, dict):
        for k, v in obj.items():
            if str(k) == str(vehicle_type_id):
                try:
                    return float(v)
                except Exception:
                    return np.nan
        # Some dicts use nested structures
        # Try common pattern: {"vehicle_types": [{"vehicle_type_id": "...", "count": ...}, ...]}
        for nested_key in ("vehicle_types", "types", "vehicle_types_available"):
            nested = obj.get(nested_key)
            if isinstance(nested, (list, dict)):
                return _extract_count_for_type(nested, vehicle_type_id)
        return np.nan
    return np.nan

# Get per-station available count for a vehicle type from several possible columns
def get_available_series_for_type(df, vehicle_type_id):
    candidate_cols = [
        "vehicle_types_available",
        "num_bikes_available_types",
        "num_vehicles_available_types",
    ]
    out = pd.Series(np.nan, index=df.index, dtype=float)
    for col in candidate_cols:
        if col in df.columns:
            s = df[col].apply(lambda x: _extract_count_for_type(x, vehicle_type_id))
            out = out.where(~s.notna(), s)  # fill NaNs in out with values from s
    # Fallback to total if still NaN everywhere
    if out.isna().all() and "num_bikes_available" in df.columns:
        out = pd.to_numeric(df["num_bikes_available"], errors="coerce").astype(float)
    return out

# Get per-station capacity for a vehicle type from several possible columns
def get_capacity_series_for_type(df, vehicle_type_id):
    candidate_cols = [
        "vehicle_type_capacity",   # GBFS v2.3: list of dicts with vehicle_type_id + count
        "vehicle_types_capacity",
        "capacity_by_type",
    ]
    out = pd.Series(np.nan, index=df.index, dtype=float)
    for col in candidate_cols:
        if col in df.columns:
            s = df[col].apply(lambda x: _extract_count_for_type(x, vehicle_type_id))
            out = out.where(~s.notna(), s)
    # Fallback to total station capacity
    if out.isna().all():
        if "capacity" in df.columns:
            out = pd.to_numeric(df["capacity"], errors="coerce").astype(float)
        else:
            # As a last resort, use bikes + docks as proxy for capacity if available
            nb = pd.to_numeric(df.get("num_bikes_available", np.nan), errors="coerce")
            nd = pd.to_numeric(df.get("num_docks_available", np.nan), errors="coerce")
            out = (nb.fillna(0) + nd.fillna(0)).astype(float)
    return out

# Prepare merged data
df = feed.merged_stations()

# Filter by region_id '949' (coerce to string for robust comparison)
if "region_id" in df.columns:
    region_mask = df["region_id"].astype(str) == "949"
    df_region = df.loc[region_mask].copy()
else:
    # If region_id is not available, no stations meet the specified region filter
    df_region = df.iloc[0:0].copy()

vehicle_type_id = "mv_rad"

# Compute per-station available for this type and capacity
avail = get_available_series_for_type(df_region, vehicle_type_id)
cap = get_capacity_series_for_type(df_region, vehicle_type_id)

# Valid stations: positive capacity and known availability
valid = cap > 0
ratios = (avail.astype(float) / cap.astype(float)).where(valid)

# Average utilization across valid stations
avg_util = float(ratios.mean()) if ratios.notna().any() else None

# Compose result
info_used = []
# Detect which fields were actually used for availability
for col in ["vehicle_types_available", "num_bikes_available_types", "num_vehicles_available_types"]:
    if col in df_region.columns:
        if df_region[col].notna().any():
            info_used.append(f"availability:{col}")
