import json

df = feed.station_status.copy()

# Filter to renting stations if flag exists
if "is_renting" in df.columns:
    with pd.option_context('mode.chained_assignment', None):
        df = df[df["is_renting"].astype(float) == 1]

# Prepare a series for electric-assist bike counts
e_counts = pd.Series(0.0, index=df.index, dtype=float)

def parse_json_if_str(val):
    if isinstance(val, str):
        try:
            return json.loads(val)
        except Exception:
            return None
    return val

# Option 1: Direct num_ebikes_available field
if "num_ebikes_available" in df.columns:
    e_counts = pd.to_numeric(df["num_ebikes_available"], errors="coerce").fillna(0.0).astype(float)

# Option 2: num_bikes_available_types dict with keys like ebike/electric_assist/electric
elif "num_bikes_available_types" in df.columns:
    def count_from_types(val):
        obj = parse_json_if_str(val)
        if isinstance(obj, dict):
            total = 0.0
            for k, v in obj.items():
                key = str(k).lower()
                if any(t in key for t in ["ebike", "e-bike", "electric_assist", "electric-assist", "electric_bike", "electricbike", "electric"]):
                    try:
                        total += float(v) if v is not None else 0.0
                    except Exception:
                        pass
            return total
        elif isinstance(obj, list):
            total = 0.0
            for item in obj:
                if not isinstance(item, dict):
                    continue
                key = str(item.get("type") or item.get("bike_type") or item.get("name") or "").lower()
                if any(t in key for t in ["ebike", "e-bike", "electric_assist", "electric-assist", "electric_bike", "electricbike", "electric"]):
                    v = item.get("count") or item.get("num_bikes_available") or item.get("quantity")
                    try:
                        total += float(v) if v is not None else 0.0
                    except Exception:
                        pass
            return total
        return 0.0

    e_counts = df["num_bikes_available_types"].map(count_from_types).fillna(0.0).astype(float)

# Option 3: vehicle_types_available referencing vehicle_type_id, use vehicle_types metadata
elif "vehicle_types_available" in df.columns and getattr(feed, "vehicle_types", None) is not None and not feed.vehicle_types.empty and "vehicle_type_id" in feed.vehicle_types.columns:
    vdf = feed.vehicle_types.copy()
    # Identify vehicle_type_ids that are electric(-assist) bicycles
    mask = pd.Series(True, index=vdf.index)
    if "propulsion_type" in vdf.columns:
        mask &= vdf["propulsion_type"].astype(str).str.lower().isin(["electric_assist", "electric"])
    if "form_factor" in vdf.columns:
        mask &= vdf["form_factor"].astype(str).str.lower().isin(["bicycle", "bike"])
    elec_type_ids = set(vdf.loc[mask, "vehicle_type_id"].astype(str).tolist())

    def count_from_vehicle_types(val):
        obj = parse_json_if_str(val)
        if not isinstance(obj, list) or not elec_type_ids:
            return 0.0
        total = 0.0
        for item in obj:
            if not isinstance(item, dict):
                continue
            vt_id = item.get("vehicle_type_id")
            if vt_id is None:
                continue
            if str(vt_id) in elec_type_ids:
                cnt = item.get("count") or item.get("num_bikes_available") or item.get("available") or 0
                try:
                    total += float(cnt) if cnt is not None else 0.0
                except Exception:
                    pass
        return total

    e_counts = df["vehicle_types_available"].map(count_from_vehicle_types).fillna(0.0).astype(float)

# Determine station with max electric-assist bikes
station_id_str = None
if not df.empty:
    # In case e_counts was not set above (no matching columns), fall back to zeros
    if e_counts is None or e_counts.shape[0] != df.shape[0]:
        e_counts = pd.Series(0.0, index=df.index, dtype=float)
    # If there are multiple maxima, idxmax returns the first occurrence
    try:
        idx = e_counts.idxmax()
        station_id_str = str(df.loc[idx, "station_id"]) if "station_id" in df.columns else None
    except Exception:
        station_id_str = None

result = {"answer": station_id_str}
