    vt_l = vt.copy()
    for col in ["form_factor", "name", "vehicle_type_name", "type_name"]:
        if col in vt_l.columns:
            vt_l[col] = vt_l[col].astype(str).str.lower()
    is_cargo_mask = pd.Series(False, index=vt_l.index)
    if "form_factor" in vt_l.columns:
        is_cargo_mask = is_cargo_mask | vt_l["form_factor"].str.contains("cargo", na=False)
    for name_col in ["name", "vehicle_type_name", "type_name"]:
        if name_col in vt_l.columns:
            is_cargo_mask = is_cargo_mask | vt_l[name_col].str.contains("cargo", na=False)
    if "vehicle_type_id" in vt_l.columns:
        cargo_ids = set(vt_l.loc[is_cargo_mask, "vehicle_type_id"].astype(str).tolist())

# Helper to decide if a bikes-available-types entry is a cargo bike
def entry_is_cargo(d):
    if not isinstance(d, dict):
        return False
    # Prefer explicit form_factor if present
    ff = d.get("form_factor")
    if ff is not None:
        ff_str = str(ff).lower()
        if "cargo" in ff_str:
            return True
    # Fallback to vehicle_type_id lookup
    vtid = d.get("vehicle_type_id")
    if vtid is not None and str(vtid) in cargo_ids:
        return True
    # As a last resort, check name-like fields for "cargo"
    for k in ("name", "vehicle_type_name", "type_name"):
        if k in d and isinstance(d[k], (str, bytes)):
            if "cargo" in str(d[k]).lower():
                return True
    return False

# Compute cargo counts per station from station_status if possible
ss = feed.station_status.copy()
if "is_renting" in ss.columns:
    # Keep only stations currently renting
    try:
        renting_mask = (ss["is_renting"].astype(int) == 1)
    except Exception:
        renting_mask = ss["is_renting"] == 1
    ss = ss[renting_mask].copy()

cargo_counts = None
list_cols = [c for c in ss.columns if c in ["num_bikes_available_types", "vehicle_types_available", "bikes_available_types"]]
if list_cols:
    col = list_cols[0]
    items_series = ss[col].apply(to_list)
    def count_cargo(items):
        if not isinstance(items, list):
            return 0
        total = 0
        for d in items:
            if entry_is_cargo(d):
                try:
                    cnt = int(float(d.get("count", 0)))
                except Exception:
                    cnt = 0
                total += cnt
        return total
    ss = ss.copy()
    ss["cargo_bikes_available"] = items_series.apply(count_cargo)
    cargo_counts = ss[["station_id", "cargo_bikes_available"]].copy()
else:
    # Fallback: try free_bike_status if it contains station_id and vehicle info
    fbs = feed.free_bike_status
    if isinstance(fbs, pd.DataFrame) and not fbs.empty and "station_id" in fbs.columns:
        f = fbs.copy()
        # Only available vehicles if flags exist
        for flag in ["is_reserved", "is_disabled"]:
            if flag in f.columns:
                try:
                    f = f[f[flag].fillna(0).astype(int) == 0]
                except Exception:
                    f = f[f[flag] == 0]
        # Determine cargo vehicles
        cargo_mask = pd.Series(False, index=f.index)
        for col in ["form_factor", "name", "vehicle_type_name", "type_name"]:
            if col in f.columns:
                cargo_mask = cargo_mask | f[col].astype(str).str.lower().str.contains("cargo", na=False)
        if "vehicle_type_id" in f.columns and cargo_ids:
            cargo_mask = cargo_mask | f["vehicle_type_id"].astype(str).isin(cargo_ids)
        f_cargo = f[cargo_mask & f["station_id"].notna()]
        if not f_cargo.empty:
            grouped = f_cargo.groupby("station_id").size().reset_index(name="cargo_bikes_available")
            cargo_counts = grouped.rename(columns={"station_id": "station_id"})
        else:
            cargo_counts = pd.DataFrame(columns=["station_id", "cargo_bikes_available"])
    else:
        cargo_counts = pd.DataFrame(columns=["station_id", "cargo_bikes_available"])

# Select station_id with maximum cargo bikes
station_id_answer = None
if isinstance(cargo_counts, pd.DataFrame) and not cargo_counts.empty:
    # Ensure types
    cargo_counts["cargo_bikes_available"] = pd.to_numeric(cargo_counts["cargo_bikes_available"], errors="coerce").fillna(0).astype(int)
    # If station_status path used, there should be one row per station; ensure aggregation in case of duplicates
    cargo_agg = cargo_counts.groupby("station_id", as_index=False)["cargo_bikes_available"].sum()
    # Choose the station with the highest count; in case of ties, take the first by descending count then by station_id
    cargo_agg = cargo_agg.sort_values(by=["cargo_bikes_available", "station_id"], ascending=[False, True])
    if not cargo_agg.empty:
        station_id_answer = str(cargo_agg.iloc[0]["station_id"])

result = {"answer": station_id_answer if station_id_answer is not None else ""}

