# Helper to safely parse JSON-like strings
def _maybe_parse_json(x):
    if isinstance(x, (list, dict)) or pd.isna(x):
        return x
    if isinstance(x, str):
        s = x.strip()
        if (s.startswith("{") and s.endswith("}")) or (s.startswith("[") and s.endswith("]")):
            try:
                return json.loads(s)
            except Exception:
                return x
    return x

# Extract per-type availability mapping from a row; prioritize vehicle_types_available over num_bikes_available_types
def extract_type_counts(row):
    # Try GBFS v2.3+ field: vehicle_types_available (array of {vehicle_type_id, count})
    vta = row.get("vehicle_types_available")
    vta = _maybe_parse_json(vta)
    type_counts = {}
    if isinstance(vta, list):
        for item in vta:
            if not isinstance(item, dict):
                continue
            # Prefer 'vehicle_type_id' key
            vt = item.get("vehicle_type_id")
            # Fallback: some feeds might use 'type_id' or 'type'
            if vt is None:
                vt = item.get("type_id", item.get("type"))
            # Determine count field
            cnt = None
            for k in ["count", "num_bikes_available", "available", "quantity"]:
                if k in item:
                    cnt = item[k]
                    break
            try:
                cnt = float(cnt) if cnt is not None else 0.0
            except Exception:
                cnt = 0.0
            if vt is not None:
                type_counts[str(vt)] = type_counts.get(str(vt), 0.0) + cnt
    elif isinstance(vta, dict):
        # Some feeds might provide a dict keyed by vehicle_type_id
        for k, v in vta.items():
            if isinstance(v, dict):
                cnt = v.get("count", v.get("num_bikes_available", v.get("available", v.get("quantity", 0))))
            else:
                cnt = v
            try:
                cnt = float(cnt) if cnt is not None else 0.0
            except Exception:
                cnt = 0.0
            type_counts[str(k)] = type_counts.get(str(k), 0.0) + cnt

    if type_counts:
        return type_counts

    # Fallback: older GBFS field num_bikes_available_types (could be dict like {'mechanical': n, 'ebike': m})
    nbat = row.get("num_bikes_available_types")
    nbat = _maybe_parse_json(nbat)
    if isinstance(nbat, dict):
        for k, v in nbat.items():
            # values may be numeric or dicts with 'count'
            if isinstance(v, dict):
                cnt = v.get("count", v.get("num_bikes_available", v.get("available", v.get("quantity", 0))))
            else:
                cnt = v
            try:
                cnt = float(cnt) if cnt is not None else 0.0
            except Exception:
                cnt = 0.0
            type_counts[str(k)] = type_counts.get(str(k), 0.0) + cnt
    elif isinstance(nbat, list):
        # Some feeds encode as list of dicts
        for item in nbat:
            if not isinstance(item, dict):
                continue
            # Use a generic type key if vehicle_type_id not present
            vt = item.get("vehicle_type_id", item.get("type_id", item.get("type")))
            if vt is None:
                # create a synthetic key based on available keys
                vt = "_".join(sorted([str(k) for k in item.keys() if k not in ("count","num_bikes_available","available","quantity")])) or "unknown"
            cnt = None
            for k in ["count", "num_bikes_available", "available", "quantity"]:
                if k in item:
                    cnt = item[k]
                    break
            try:
                cnt = float(cnt) if cnt is not None else 0.0
            except Exception:
                cnt = 0.0
            type_counts[str(vt)] = type_counts.get(str(vt), 0.0) + cnt

    return type_counts

# Apply extraction and count distinct types with count > 0
if df.shape[0] == 0:
    avg_types = 0.0
else:
    type_maps = df.apply(extract_type_counts, axis=1)
    # For stations where we couldn't parse any type info, mark as NaN to exclude from average
    def count_positive_types(m):
        if not isinstance(m, dict) or len(m) == 0:
            return np.nan
        return float(sum(1 for c in m.values() if pd.notna(c) and float(c) > 0))

    counts = type_maps.apply(count_positive_types)
    # If all are NaN (no per-type info), set average to 0.0; else compute mean over available stations
    if counts.notna().any():
        avg_types = float(counts.mean())
    else:
        avg_types = 0.0

result = {"answer": float(avg_types)}
